search.query:
index=host sourcetype="l2t:winevtx" host=$hostFilter$ | rex field=display_name "\\(?<winevent_source>[^\\]+)\.evtx" | search winevent_source="Security" | rex field=message "\[(?<event_id>\d+)\s" | search event_id=4688 | rex field=message "Process Name:\s+(?<process_name>[^\s
]+)" | rex field=message "Creator Process ID:\s+(?<parent_pid>[^\s
]+)" | rex field=message "New Process ID:\s+(?<pid>[^\s
]+)" | rex field=message "Account Name:\s+(?<username>[^\s
]+)" | stats count by process_name, username | sort -count | head 20
